import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { mechanicService } from '../services/mechanicService';
import { MaintenanceLog, SOSAlert, AlertPriority } from '../types';
import { useAuth } from './useAuth';

// Query Keys
export const maintenanceKeys = {
  machines: {
    all: ['machines'] as const,
    detail: (id: string | number) => ['machines', id] as const,
    history: (id: string | number) => ['machines', id, 'history'] as const,
    sos: (id: string | number) => ['machines', id, 'sos'] as const,
  },
  alerts: {
    all: ['sos'] as const,
    list: (filters: any) => ['sos', 'list', filters] as const,
    detail: (id: string) => ['sos', 'detail', id] as const,
  },
  maintenance: {
    all: ['maintenance'] as const,
    list: (filters: any) => ['maintenance', 'list', filters] as const,
  }
};

// --- Machines ---

export const useMachines = () => {
  return useQuery({
    queryKey: maintenanceKeys.machines.all,
    queryFn: async () => {
        const machines = await mechanicService.getAllMachines();
        return { machines };
    },
  });
};

export const useMachine = (id: number | string) => {
  return useQuery({
    queryKey: maintenanceKeys.machines.detail(id),
    queryFn: async () => {
        const machine = await mechanicService.getMachineById(id.toString());
        return { machine };
    },
    enabled: !!id,
  });
};

export const useMachineMaintenanceHistory = (id: number | string) => {
    return useQuery({
        queryKey: maintenanceKeys.machines.history(id),
        queryFn: async () => {
            const logs = await mechanicService.getMachineMaintenanceHistory(id.toString());
            return { logs };
        },
        enabled: !!id
    });
};

export const useMachineSOSHistory = (id: number | string) => {
    return useQuery({
        queryKey: maintenanceKeys.machines.sos(id),
        queryFn: async () => {
            const alerts = await mechanicService.getAllAlerts({ machineId: id.toString() });
            return { alerts };
        },
        enabled: !!id
    });
}

// --- SOS Alerts ---

export const useSOSAlerts = (filters?: { status?: string; priority?: string; machineId?: string }) => {
  return useQuery({
    queryKey: maintenanceKeys.alerts.list(filters || {}),
    queryFn: async () => {
        // Map filters if needed, service expects specific types but usually string works
        const alerts = await mechanicService.getAllAlerts(filters as any);
        return { alerts };
    },
     refetchInterval: 15000, 
  });
};

export const useCreateSOSAlert = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: (data: { machineId: string; priority: AlertPriority; problemDescription: string }) => mechanicService.createAlert(data),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: maintenanceKeys.alerts.all });
            queryClient.invalidateQueries({ queryKey: maintenanceKeys.machines.all });
        }
    });
}

export const useAssignAlert = () => {
    const queryClient = useQueryClient();
    const { useCurrentUser } = useAuth();
    const { data: user } = useCurrentUser();

    return useMutation({
        mutationFn: ({ alertId }: { alertId: string }) => {
            if (!user?.id) throw new Error("User not authenticated");
            return mechanicService.assignAlert(alertId, user.id);
        },
        onSuccess: () => {
             queryClient.invalidateQueries({ queryKey: maintenanceKeys.alerts.all });
        }
    })
}

export const useUpdateAlertStatus = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ alertId, status }: { alertId: string; status: string }) => mechanicService.updateAlert(alertId, { status: status as any }),
        onSuccess: () => {
             queryClient.invalidateQueries({ queryKey: maintenanceKeys.alerts.all });
        }
    });
}

export const useResolveAlert = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: ({ alertId, resolutionNotes, partsUsed, timeSpent }: { alertId: string, resolutionNotes: string, partsUsed?: string, timeSpent?: number }) =>
            mechanicService.resolveAlert(alertId, resolutionNotes), 
        onSuccess: () => {
             queryClient.invalidateQueries({ queryKey: maintenanceKeys.alerts.all });
             queryClient.invalidateQueries({ queryKey: maintenanceKeys.machines.all });
        }
    });
}

// --- Maintenance Logs ---

export const useMaintenanceLogs = (filters?: { limit?: number }) => {
    return useQuery({
        queryKey: maintenanceKeys.maintenance.list(filters || {}),
        queryFn: async () => {
            const logs = await mechanicService.getAllMaintenanceLogs(filters);
            return { logs };
        }
    });
};

export const useCreateMaintenanceLog = () => {
    const queryClient = useQueryClient();
    return useMutation({
        mutationFn: (data: Partial<MaintenanceLog>) => mechanicService.createMaintenanceLog(data),
        onSuccess: (data) => {
             queryClient.invalidateQueries({ queryKey: maintenanceKeys.maintenance.all });
             if (data.machineId) {
                  queryClient.invalidateQueries({ queryKey: maintenanceKeys.machines.detail(data.machineId) });
             }
        }
    });
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { mechanicService } from '../services/mechanicService';
import { MaintenanceLog, SOSAlert, AlertPriority } from '../types';

// Query Keys
export const mechanicKeys = {
  machines: {
    all: ['machines'] as const,
    detail: (id: string) => ['machines', id] as const,
    history: (id: string) => ['machines', id, 'history'] as const,
  },
  alerts: {
    all: ['sos'] as const,
    list: (filters: any) => ['sos', 'list', filters] as const,
    detail: (id: string) => ['sos', 'detail', id] as const,
  },
  maintenance: {
    all: ['maintenance'] as const,
    list: (filters: any) => ['maintenance', 'list', filters] as const,
  }
};

export const useMechanic = () => {
  const queryClient = useQueryClient();

  // --- Machines ---

  const useMachines = () => {
    return useQuery({
      queryKey: mechanicKeys.machines.all,
      queryFn: () => mechanicService.getAllMachines(),
    });
  };

  const useMachine = (id: string) => {
    return useQuery({
      queryKey: mechanicKeys.machines.detail(id),
      queryFn: () => mechanicService.getMachineById(id),
      enabled: !!id,
    });
  };

  // --- SOS Alerts ---

  const useSOSAlerts = (filters?: { status?: string; priority?: AlertPriority; machineId?: string }) => {
    return useQuery({
      queryKey: mechanicKeys.alerts.list(filters || {}),
      queryFn: () => mechanicService.getAllAlerts(filters as any),
      refetchInterval: 15000, // Frequent refresh for alerts
    });
  };

  const useCreateSOSAlert = () => {
    return useMutation({
      mutationFn: (data: { machineId: string; priority: AlertPriority; problemDescription: string }) => mechanicService.createAlert(data),
      onSuccess: () => {
        queryClient.invalidateQueries({ queryKey: mechanicKeys.alerts.all });
        // Update dashboard stats
        queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      },
    });
  };

  const useResolveAlert = () => {
    return useMutation({
      mutationFn: ({ id, notes }: { id: string; notes: string }) => mechanicService.resolveAlert(id, notes),
      onSuccess: () => {
        queryClient.invalidateQueries({ queryKey: mechanicKeys.alerts.all });
      },
    });
  };

  // --- Maintenance ---

  const useMaintenanceLogs = (filters?: any) => {
    return useQuery({
      queryKey: mechanicKeys.maintenance.list(filters || {}),
      queryFn: () => mechanicService.getAllMaintenanceLogs(filters),
    });
  };

  const useCreateMaintenanceLog = () => {
    return useMutation({
      mutationFn: (data: Partial<MaintenanceLog>) => mechanicService.createMaintenanceLog(data),
      onSuccess: (data) => {
        queryClient.invalidateQueries({ queryKey: mechanicKeys.maintenance.all });
        queryClient.invalidateQueries({ queryKey: mechanicKeys.machines.detail(data.machineId) });
        queryClient.invalidateQueries({ queryKey: mechanicKeys.machines.history(data.machineId) });
      },
    });
  };

  return {
    useMachines,
    useMachine,
    useSOSAlerts,
    useCreateSOSAlert,
    useResolveAlert,
    useMaintenanceLogs,
    useCreateMaintenanceLog,
  };
};
